namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Integration;
public sealed class AstronomyKnowledgeFoundationArchitectureTests
{ static readonly string Root=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../..")); static readonly string Prod=Path.Combine(Root,"src/Astronomy.MediaFactory.Core/KnowledgeFoundation/Integration"); static readonly string Tests=Path.Combine(Root,"tests/Astronomy.MediaFactory.Tests/KnowledgeFoundation/Integration");
 [Fact]public void Required_files_exist_and_are_non_empty(){Assert.True(Directory.Exists(Prod));foreach(var f in RequiredProductionFiles())Assert.True(new FileInfo(Path.Combine(Prod,f)).Length>0,f);foreach(var f in RequiredTestFiles())Assert.True(new FileInfo(Path.Combine(Tests,f)).Length>0,f);} 
 [Fact]public void Root_registration_calls_frozen_registration_methods(){var text=File.ReadAllText(Path.Combine(Prod,"AstronomyKnowledgeFoundationRegistrationExtensions.cs"));foreach(var call in new[]{"AddAstronomyTypedKnowledge","AddAstronomyKnowledgeValidation","AddAstronomyCrossDomainValidation","AddAstronomyKnowledgeGraphValidation","AddAstronomyKnowledgeCatalog","AddAstronomyKnowledgeQueryModel","AddAstronomyKnowledgeQueryExecution"})Assert.Contains(call,text,StringComparison.Ordinal);} 
 [Fact]public void Production_integration_has_no_forbidden_architecture_usages(){var forbidden=new[]{"DbContext","DbSet","AddDbContext","Repository","IRepository","SaveChanges","Controller","HttpClient","BackgroundService","IHostedService","Task.Run","Parallel.","AsParallel","ConcurrentDictionary","MemoryCache","IMemoryCache","DateTime.Now","DateTime.UtcNow","DateTimeOffset.Now","DateTimeOffset.UtcNow","Activator.CreateInstance","Assembly.GetTypes","AppDomain.CurrentDomain","BuildServiceProvider","IServiceProvider","IServiceScopeFactory","DynamicInvoke","Compile(","JsonSerializer","Newtonsoft","InferKnowledge","GenerateKnowledge","PredictEvent","Ephemeris"};foreach(var path in Directory.GetFiles(Prod,"*.cs")){var text=File.ReadAllText(path);foreach(var token in forbidden)Assert.DoesNotContain(token,text,StringComparison.Ordinal);}}
 static string[] RequiredProductionFiles()=>["AstronomyKnowledgeFoundationCapabilityKind.cs","AstronomyKnowledgeFoundationCapabilityId.cs","AstronomyKnowledgeFoundationCapabilityDescriptor.cs","AstronomyKnowledgeFoundationCapabilitySnapshot.cs","IAstronomyKnowledgeFoundationCapabilities.cs","AstronomyKnowledgeFoundationCapabilities.cs","AstronomyKnowledgeFoundationRegistrationOptions.cs","AstronomyKnowledgeFoundationRegistrationExtensions.cs","AstronomyKnowledgeFoundationCompatibilityReport.cs","IAstronomyKnowledgeFoundationCompatibilityVerifier.cs","AstronomyKnowledgeFoundationCompatibilityVerifier.cs","AstronomyKnowledgeFoundationCapabilityCatalog.cs"];
 static string[] RequiredTestFiles()=>["KnowledgeFoundationIntegrationFixture.cs","AstronomyKnowledgeFoundationCapabilityIdTests.cs","AstronomyKnowledgeFoundationCapabilityDescriptorTests.cs","AstronomyKnowledgeFoundationCapabilitySnapshotTests.cs","AstronomyKnowledgeFoundationCapabilitiesTests.cs","AstronomyKnowledgeFoundationRegistrationTests.cs","AstronomyKnowledgeFoundationCompatibilityVerifierTests.cs","AstronomyKnowledgeFoundationEndToEndTests.cs","AstronomyKnowledgeFoundationIntegrationTests.cs","AstronomyKnowledgeFoundationArchitectureTests.cs"];}
